//counting wordings

function limitWordInput(c_maxWordLength,evnt)
{
var v_newText=evnt.newText;

v_totalWords=(v_newText==""?0:getWordCount(v_newText))

if (v_totalWords > c_maxWordLength)
{
	var v_Start=evnt.selStart;
	var v_end=evnt.selEnd;
	var v_insertText=evnt.change;

	var v_prevText=evnt.prevText;
	var v_totalWords=0;
	var v_textBeforeCursor="";
	var v_texAfterCursor="";
	var v_noWordsBeingInserted=0;
	var v_noWordsBefore=0;
	var v_noWordsAfter=0;
	var v_noWordsToReachMax=0;

	//Text is selected for replacement
	if (v_Start!=v_end)
	{
		//xfa.host.messageBox("Text is selected for replacement");
		v_textBeforeCursor=(v_Start==0?"":v_prevText.substring(0,v_Start));
		v_texAfterCursor=v_prevText.substring(v_end);

	}
	//text is being inserted at the beginning of previous input
	else if (v_Start!=v_prevText.length && v_Start==0)
	{
		//xfa.host.messageBox("text is being inserted at the beginning of previous input");
		v_textBeforeCursor=""
		v_texAfterCursor=v_prevText

	}
	//text is being inserted in between previous input
	else if (v_Start!=v_prevText.length)
	{
		//xfa.host.messageBox("text is being inserted in between previous input");
		v_textBeforeCursor=v_prevText.substring(0,v_Start);
		v_texAfterCursor=v_prevText.substring(v_Start);
	}
	//text is being inserted at the end of previous input
	else 
	{
		//xfa.host.messageBox("text is being inserted at the end of previous input");
		v_textBeforeCursor=v_prevText
		v_texAfterCursor=""
	}
    //xfa.host.messageBox("v_textBeforeCursor -" + v_textBeforeCursor + "-");
    //xfa.host.messageBox("v_texAfterCursor -" + v_texAfterCursor + "-");
    //xfa.host.messageBox("v_insertText -" + v_insertText + "-");
    v_noWordsBeingInserted=(v_insertText==""?0:getWordCount(v_insertText))
    v_noWordsBefore=(v_textBeforeCursor==""?0:getWordCount(v_textBeforeCursor))
    v_noWordsAfter=(v_texAfterCursor==""?0:getWordCount(v_texAfterCursor))


	v_noWordsToReachMax=c_maxWordLength -(v_noWordsBefore + v_noWordsAfter)

	//xfa.host.messageBox("getPositionNthWord " + getPositionNthWord(v_insertText,v_noWordsToReachMax));

	//If first word in text before the cursor is joining the first word in the insert text becoming one word
	if (v_noWordsBefore > 0 && !isCharWhitespace(v_textBeforeCursor[v_textBeforeCursor.length-1]) && !isCharWhitespace(v_insertText[0]))
		v_noWordsToReachMax=v_noWordsToReachMax + 1
	//If first word in text after the cursor is joining the last word in the insert text becoming one word
	//if (v_noWordsAfter > 0 &&  !isCharWhitespace(v_texAfterCursor[0]))
 	//	v_noWordsToReachMax=v_noWordsToReachMax + 1

	//xfa.host.messageBox("v_noWordsToReachMax " + v_noWordsToReachMax);

 	if (v_noWordsToReachMax<=0)
	{
		evnt.change = "";
    	evnt.selStart = evnt.selEnd = 0;
    	evnt.commitKey
    }
 	else if (v_noWordsToReachMax==c_maxWordLength)
	{

    	xfa.host.messageBox("You have reached the maximum of "+c_maxWordLength+" wordings",3)
    }    
	else
	{
		evnt.change= v_insertText.substring(0,getPositionNthWord(v_insertText,v_noWordsToReachMax)+1);
	}
	xfa.host.messageBox("You have reached the maximum wordings allowed", "Maximum of Wordings", 3);
}
}
//Get the index position immediately after the end of the nth word in the input string
function getPositionNthWord(str,nth)
{

	var patt=/\b\S+\b/g;
    var cnt=0
    var lst=0

	if (str==null ||str=="")
		return -1
	patt.compile(patt);	
	while (patt.test(str)==true && cnt< nth) 
  	{
  		lst=patt.lastIndex
  		cnt=cnt +1;
 	 }
 	return lst;

}
//Count the number of words in an input string
function getWordCount(str)
{
	if (str==null ||str=="")
		return 0
	else
		return str.split(/\b\S+\b/g).length -1

}
//Check if input character is a whitespace
function isCharWhitespace(chr)
{
	var patt=/\s/
	if (chr==null ||chr=="")
		return false;
	else 
		return patt.test(chr)

}

