function validateDateExit(evnt,pattern)
{

	var changeValue="" + evnt.target.rawValue;
	if (evnt.target.rawValue!=null)
	{
		var arr=pattern.split(/-|\//) 
		var arr2=evnt.target.rawValue.split(/-|\//) 
		if (arr.length==3 && arr2.length==3)
		{


			arr2=evnt.target.formattedValue.split(/-|\//) 


			if ((arr[0].charAt(0)=="y" && (arr2[0].length!=4 || arr2[1].length< 1  || arr2[1].length> 2 || arr2[2].length< 1 || arr2[2].length> 2)) 
			|| (arr[1].charAt(0)=="y" && (arr2[1].length!=4  || arr2[0].length< 1  || arr2[0].length> 2 || arr2[2].length< 1 || arr2[2].length> 2)) 
			|| (arr[2].charAt(0)=="y" && (arr2[2].length!=4  || arr2[0].length< 1  || arr2[0].length> 2 || arr2[1].length< 1 || arr2[1].length> 2)))
			{
				xfa.host.messageBox(msgDateE);
		    	xfa.host.resetData(evnt.target.somExpression);
		    	xfa.host.setFocus(evnt.target.somExpression)

			}	
			else
			{
				var dte=util.scand(pattern, evnt.target.formattedValue); 

				if (!dte)
				{
			    	// cancel the change
			    	//xfa.host.messageBox("" + dte)
			    	xfa.host.messageBox(msgDateE);
			    	xfa.host.resetData(evnt.target.somExpression);
			    	xfa.host.setFocus(evnt.target.somExpression)
			   	}
			   	else
			   	{
			   		//in case separator is a combination of - and /
			   		if (pattern.indexOf("-")!=-1)
			   			evnt.target.rawValue=evnt.target.formattedValue.replace(/\//,"-")
			   		else
			   			evnt.target.rawValue=evnt.target.formattedValue.replace(/-/g,"/")

			   	}
			}
		 }
		 else
		 {

			 xfa.host.messageBox(msgDateE);
		     xfa.host.resetData(evnt.target.somExpression);
		     xfa.host.setFocus(evnt.target.somExpression)


		 }

    }
}
function validatePhoneExit(evnt)
{


// pattern to match the phone number
var pattern = /^[0-9]{3}[\s-]?[0-9]{3}[\s-]?[0-9]{4}$/;
var pattern2 = /^\({1}[0-9]{3}\){1}\s?[0-9]{3}[\s-]?[0-9]{4}$/;



if(evnt.target.rawValue!=null)
{	
	// if user's input does NOT match the pattern, display a validation message
	if(!evnt.target.rawValue.match(pattern) && !evnt.target.rawValue.match(pattern2))
	{
		xfa.host.messageBox(msgTelE);
		xfa.host.setFocus(evnt.target.name);
		evnt.target.rawValue="";
	}
	else
	{
		var displayPat = /[\(\)\s-]/;
		var result = evnt.target.rawValue.split(displayPat);
		result = result.join("");
		var finalResult = result.substring(0,3) + "-" + result.substring(3,6) + "-" + result.substring(6,10); 
		evnt.target.rawValue = finalResult;
	}
 }

}


