function validatePhoneExtChange(evnt)
{
	var fullValue="" + evnt.fullText
	//fullValue = util.printx("999999999999999", fullValue);
	if (fullValue.match("^[0-9\-]*$") == null)
	{
    	// cancel the change
    	evnt.change = "";
    	//evnt.selStart = evnt.selEnd = 0;
    	//xfa.event.commitKey

   	}
   	else 
	{
		var pos=0;
		var fnd=false;
		while (pos!=-1 && fnd==false)
		{
			pos=fullValue.indexOf("-", pos)
			if (pos!=-1)
			{
				if (pos!=10)
					fnd=true;
				pos=pos +1;
			}

		}
		if (fnd==true)
		{
			evnt.change = "";
    			evnt.selStart = evnt.selEnd = 0;
    			xfa.event.commitKey

   		}
   		else if (fullValue.length > 16)
   		{
   			// cancel the change
    			evnt.change = "";
    			evnt.selStart = evnt.selEnd = 0;
    			xfa.event.commitKey
        }
   		else if (fullValue.length >= 11)
   		{
   			if (fullValue.charAt(10)!="-")
   			{
    				evnt.change = "";
    				evnt.selStart = evnt.selEnd = 0;
    				xfa.event.commitKey
    			}
        }

	}



}



