function validatePhoneExit(evnt)
{

var changeValue="" + evnt.target.rawValue;

	if (evnt.target.rawValue!=null)
	if (changeValue.length > 0 && changeValue.length < 10)
	{
    	// cancel the change
    	xfa.host.messageBox("Invalid telephone number");
    	xfa.host.resetData(evnt.target.somExpression);
    	xfa.host.setFocus(evnt.target.somExpression)
   	}

}
function validatePostalCodeExit(evnt)
{

var changeValue="" + evnt.target.rawValue;
changeValue=changeValue.replace( /\s/g, "" ); 
	if ( evnt.target.rawValue!=null)
	if ((changeValue.length > 0 && changeValue.length < 6) || changeValue.match("^[a-zA-Z][0-9][a-zA-Z][0-9][a-zA-Z][0-9]$") == null)
	{
    	// cancel the change
    	xfa.host.messageBox("Invalid Postal Code");
    	xfa.host.resetData(evnt.target.somExpression);
    	xfa.host.setFocus(evnt.target.somExpression)
   	}
    else
    evnt.target.rawValue=changeValue.substring(0,3) + " " + changeValue.substring(3);
}

