function checkManadatory()
{
var manFieldsArray=[];

	manFieldsArray.push([page1.body.personalInfo.last.lastName, "Contact Information - Last Name is mandatory."]);
	manFieldsArray.push([page1.body.personalInfo.first.firstName,"Contact Information - First Name is mandatory."]);
	manFieldsArray.push([page1.body.personalInfo.streetNo,"Current Address - Street Number is mandatory."]);
	manFieldsArray.push([page1.body.personalInfo.streetName,"Current Address - Street Name is mandatory."]);

	manFieldsArray.push([page1.body.personalInfo.city, "Current Address - City is mandatory."]);
	manFieldsArray.push([page1.body.personalInfo.province,"Current Address - Province is mandatory."]);
	manFieldsArray.push([page1.body.personalInfo.postalCode,"Current Address - Postal Code is mandatory."]);
	manFieldsArray.push([page1.body.personalInfo.telephoneNo,"Contact Information - Telephone Number is mandatory."]);


	manFieldsArray.push([page1.body.businessInfo.busLastName, "Business Information - Last Name is mandatory."]);
	manFieldsArray.push([page1.body.businessInfo.busFirstName,"Business Information - First Name is mandatory."]);
	manFieldsArray.push([page1.body.businessInfo.busStreetNo,"Mailing Address - Street Number is mandatory."]);
	manFieldsArray.push([page1.body.businessInfo.busStreetName,"Mailing Address - Street Name is mandatory."]);

	manFieldsArray.push([page1.body.businessInfo.busCity, "Mailing Address - City is mandatory."]);
	manFieldsArray.push([page1.body.businessInfo.busProvince,"Mailing Address - Province is mandatory."]);
	manFieldsArray.push([page1.body.businessInfo.busPostalCode,"Mailing Address - Postal Code is mandatory."]);
	manFieldsArray.push([page1.body.businessInfo.telephone.TelephoneNo,"Business Information - Telephone Number is mandatory."]);


	if( (page1.body.businessInfo.yes.rawValue==""|| page1.body.businessInfo.yes.rawValue==null) && 
	    (page1.body.businessInfo.no.rawValue=="" || page1.body.businessInfo.no.rawValue==null) ){	

		manFieldsArray.push([page1.body.businessInfo.yes,"'For administrative purposes for non-operational travel, the following should be attached if applicable.' is mandatory."])	
	}

//form1.page1.body.instructor.instrName

	var nodes  = xfa.resolveNodes("form1.page1.body.instructor[*]")
		 for (var i=0; i<nodes.length; i++)
		 {
		   manFieldsArray.push([nodes.item(i).instructorInfo.instructorName.instrName,"Instructor Name is mandatory."]);
		   manFieldsArray.push([nodes.item(i).instructorInfo.instructorName.evalName,"Evaluator Name is mandatory."]);		   	
		 }


//---------------------------------

	var found=false
		for (var i=0; i< manFieldsArray.length && found==false;i++)
		{
			if (manFieldsArray[i][0].rawValue==null || manFieldsArray[i][0].rawValue=="")
			{

					xfa.host.messageBox(manFieldsArray[i][1])
					xfa.host.setFocus(manFieldsArray[i][0]);

				found=true;
			}
		}
		return found;
}

//===============================================================
function LTrim( value ) {

	var re = /\s*((\S+\s*)*)/;
	return value.replace(re, "$1");

}


function RTrim( value ) {

	var re = /((\s*\S+)*)\s*/;
	return value.replace(re, "$1");

}


function trim( value ) {

	return LTrim(RTrim(value));

}
