function checkEmpty(fldName)
{ 
	var emptyBool=false
	var fld=fldName;
	if (fld!=null)
	{

		var fType
		if (typeof fld.ui!="undefined")
			fType = fld.ui.oneOfChild.className;
		else
			fType=fld.nodes.item(0).ui.oneOfChild.className;
        //xfa.host.messageBox(fType);
    	if (fType == "checkbox" && (fld.rawValue==null||fld.rawValue==""))
    	{
    		//xfa.host.messageBox("" + fld.name)
    		emptyBool=true
    	}
    	else if (fType == "checkButton" &&  (fld.rawValue==null||fld.rawValue==""||fld.rawValue=="0"||fld.rawValue=="OFF"))
    	{
    		//xfa.host.messageBox("" + fld.name)
    		emptyBool=true
    	}
    	else if (fType == "textEdit" && (fld.rawValue==null||trim(fld.rawValue)==""))
    		emptyBool=true
    	 else if (fType == "numericEdit" && ((fld.rawValue==null||fld.rawValue=="") && fld.formattedValue==""))
    		emptyBool=true
    	 else if (fType == "dateTimeEdit" && (fld.rawValue==null||trim(fld.rawValue)==""))
    		emptyBool=true
     	else if (fType == "choiceList" && (fld.rawValue==null||trim(fld.rawValue)==""))
    		emptyBool=true
      else if (fType == "imageEdit" && (fld.rawValue==null||trim(fld.rawValue)==""))
    		emptyBool=true


    	}
   return emptyBool
}

